SELECT DISTINCT OH.ORDER_ID, OH.PRODUCT_STORE_ID, OH.SALES_CHANNEL_ENUM_ID, OH.ORDER_DATE, OH.ENTRY_DATE, OH.STATUS_ID, OH.PRIORITY, OH.GRAND_TOTAL, ODR.PARTY_ID, SHOPIFY_OID.ID_VALUE, PAY.PAYMENT_TOTAL, UNMAP.UNMAPPED_ITEM_COUNT, XCM.WAITING_COUNT FROM ORDER_HEADER OH INNER JOIN ORDER_IDENTIFICATION SHOPIFY_OID ON OH.ORDER_ID = SHOPIFY_OID.ORDER_ID AND (((SHOPIFY_OID.FROM_DATE  IS NULL OR SHOPIFY_OID.FROM_DATE <= '2026-09-10 23:01:45.232000') AND (SHOPIFY_OID.THRU_DATE  IS NULL OR SHOPIFY_OID.THRU_DATE > '2026-09-10 23:01:45.232000')) AND SHOPIFY_OID.ORDER_IDENTIFICATION_TYPE_ID = 'SHOPIFY_ORD_ID') LEFT OUTER JOIN ORDER_IDENTIFICATION OID ON OH.ORDER_ID = OID.ORDER_ID AND (((OID.FROM_DATE  IS NULL OR OID.FROM_DATE <= '2026-09-10 23:01:45.232000') AND (OID.THRU_DATE  IS NULL OR OID.THRU_DATE > '2026-09-10 23:01:45.232000')) AND OID.ORDER_IDENTIFICATION_TYPE_ID = 'NETSUITE_ORDER_ID') LEFT OUTER JOIN ORDER_ROLE ODR ON OH.ORDER_ID = ODR.ORDER_ID AND (((ODR.FROM_DATE  IS NULL OR ODR.FROM_DATE <= '2026-09-10 23:01:45.232000') AND (ODR.THRU_DATE  IS NULL OR ODR.THRU_DATE > '2026-09-10 23:01:45.232000')) AND ODR.ROLE_TYPE_ID = 'BILL_TO_CUSTOMER') LEFT OUTER JOIN  LATERAL (SELECT COUNT(UOI.ORDER_ITEM_SEQ_ID) AS UNMAPPED_ITEM_COUNT FROM ORDER_ITEM UOI LEFT OUTER JOIN GOOD_IDENTIFICATION UGID ON UOI.PRODUCT_ID = UGID.PRODUCT_ID AND (((UGID.FROM_DATE  IS NULL OR UGID.FROM_DATE <= '2026-09-10 23:01:45.232000') AND (UGID.THRU_DATE  IS NULL OR UGID.THRU_DATE > '2026-09-10 23:01:45.232000')) AND UGID.GOOD_IDENTIFICATION_TYPE_ID = 'NETSUITE_PRODUCT_ID') WHERE OH.ORDER_ID = UOI.ORDER_ID AND UGID.ID_VALUE IS NULL) UNMAP ON 1=1 LEFT OUTER JOIN  LATERAL (SELECT COUNT(XOPP.ORDER_PAYMENT_PREFERENCE_ID) AS WAITING_COUNT FROM ORDER_PAYMENT_PREFERENCE XOPP LEFT OUTER JOIN INVOICE XCRI ON XOPP.CUSTOMER_RETURN_INVOICE_ID = XCRI.INVOICE_ID WHERE OH.ORDER_ID = XOPP.ORDER_ID AND (XOPP.PAYMENT_METHOD_TYPE_ID = 'EXCHANGE_CREDIT' AND XOPP.STATUS_ID IN ('PAYMENT_AUTHORIZED', 'PAYMENT_SETTLED') AND XCRI.EXTERNAL_ID IS NULL)) XCM ON 1=1 LEFT OUTER JOIN  LATERAL (SELECT SUM(OPP.MAX_AMOUNT) AS PAYMENT_TOTAL FROM ORDER_PAYMENT_PREFERENCE OPP WHERE OH.ORDER_ID = OPP.ORDER_ID AND OPP.STATUS_ID IN ('PAYMENT_AUTHORIZED', 'PAYMENT_SETTLED')) PAY ON 1=1 WHERE (OH.PRODUCT_STORE_ID = 'STORE' AND OH.ORDER_DATE > '2026-08-15T00:00:00' AND OH.ORDER_TYPE_ID = 'SALES_ORDER' AND SHOPIFY_OID.ID_VALUE IS NOT NULL AND OID.ORDER_ID IS NULL AND UNMAP.UNMAPPED_ITEM_COUNT = '0' AND XCM.WAITING_COUNT = '0' AND (PAY.PAYMENT_TOTAL >= OH.GRAND_TOTAL OR OH.GRAND_TOTAL = 0)) ORDER BY OH.ORDER_DATE ASC
